/**
 * VENDIAIDE RESPONSE PLANNER & GENERATOR — DECOUPLED RESPONSE LAYER
 *
 * Cleanly separates:
 * 1. "What should VendiAide do?" -> ResponseActionPlan (deterministic action plan)
 * 2. "How should VendiAide say it?" -> generateNaturalResponse (natural language formatter)
 *
 * 🛑 ARCHITECTURAL BOUNDARY:
 * This module NEVER mutates order state, calculates delivery fees, or mutates database state.
 * It strictly formats and plans response directives generated by the Conversation State Manager.
 */

import { ConversationStateModel } from './conversation-state-manager';
import { DemoProduct } from '../demo/demo-engine';
import { formatNaira } from '../utils/formatters';

// ============================================================================
// 1. TYPES & ACTION PLAN DEFINITIONS
// ============================================================================

export type ResponseActionType =
  | 'SHOW_CATALOG'
  | 'ANSWER_PRICE_AND_DETAILS'
  | 'PROMPT_MISSING_SIZE'
  | 'PROMPT_MISSING_COLOR'
  | 'PROMPT_MISSING_LOCATION'
  | 'PROMPT_CONFIRMATION'
  | 'EXECUTE_ORDER'
  | 'CANCEL_ORDER'
  | 'RECOVER_INTERRUPTION'
  | 'GENERAL_HELP';

export interface ResponseActionPlan {
  actionType: ResponseActionType;
  targetProduct?: DemoProduct;
  selectedSize?: string | null;
  selectedColor?: string | null;
  deliveryLocation?: string | null;
  itemPriceNaira?: number;
  deliveryFeeNaira?: number;
  totalNaira?: number;
  missingField?: 'product' | 'size' | 'color' | 'location';
}

export type PersonaTone = 'friendly_professional' | 'warm_nigerian' | 'formal';

// ============================================================================
// 2. ACTION PLANNER DETERMINATION
// ============================================================================

export function buildResponseActionPlan(
  state: ConversationStateModel,
  resolvedProduct?: DemoProduct
): ResponseActionPlan {
  if (state.cancellationStatus === 'CANCELLED') {
    return { actionType: 'CANCEL_ORDER' };
  }

  if (state.confirmationStatus === 'USER_CONFIRMED') {
    return {
      actionType: 'EXECUTE_ORDER',
      targetProduct: resolvedProduct,
      selectedSize: state.selectedSize,
      selectedColor: state.selectedColor,
      deliveryLocation: state.deliveryLocation,
      itemPriceNaira: state.orderReadiness.itemPriceNaira,
      deliveryFeeNaira: state.orderReadiness.deliveryFeeNaira,
      totalNaira: state.orderReadiness.totalNaira,
    };
  }

  if (state.orderReadiness.isComplete) {
    return {
      actionType: 'PROMPT_CONFIRMATION',
      targetProduct: resolvedProduct,
      selectedSize: state.selectedSize,
      selectedColor: state.selectedColor,
      deliveryLocation: state.deliveryLocation,
      itemPriceNaira: state.orderReadiness.itemPriceNaira,
      deliveryFeeNaira: state.orderReadiness.deliveryFeeNaira,
      totalNaira: state.orderReadiness.totalNaira,
    };
  }

  const nextMissing = state.missingFields[0];

  if (nextMissing === 'product') {
    return { actionType: 'SHOW_CATALOG', missingField: 'product' };
  }
  if (nextMissing === 'size') {
    return { actionType: 'PROMPT_MISSING_SIZE', targetProduct: resolvedProduct, missingField: 'size' };
  }
  if (nextMissing === 'color') {
    return { actionType: 'PROMPT_MISSING_COLOR', targetProduct: resolvedProduct, missingField: 'color' };
  }
  if (nextMissing === 'location') {
    return { actionType: 'PROMPT_MISSING_LOCATION', targetProduct: resolvedProduct, missingField: 'location' };
  }

  return { actionType: 'GENERAL_HELP' };
}

// ============================================================================
// 3. NATURAL LANGUAGE GENERATOR
// ============================================================================

export function generateNaturalResponse(
  plan: ResponseActionPlan,
  catalog: DemoProduct[],
  tone: PersonaTone = 'friendly_professional'
): string {
  const pName = plan.targetProduct?.name || 'item';
  const priceStr = plan.targetProduct ? formatNaira(plan.targetProduct.price_ngn) : '';
  const totalStr = plan.totalNaira ? formatNaira(plan.totalNaira) : '';
  const feeStr = plan.deliveryFeeNaira ? formatNaira(plan.deliveryFeeNaira) : '';

  switch (plan.actionType) {
    case 'CANCEL_ORDER':
      if (tone === 'warm_nigerian') {
        return 'No p, my boss! 😊 I don cancel am. Whenever you ready to check another thing, just holla me!';
      }
      if (tone === 'formal') {
        return 'Understood. Your pending order request has been cancelled. Please let us know if you require any further assistance.';
      }
      return 'No problem at all! 😊 I have cancelled that request. Let me know whenever you would like to explore our catalog again!';

    case 'EXECUTE_ORDER':
      if (tone === 'warm_nigerian') {
        return `🎉 Sharp! Your order for ${pName} (${plan.selectedSize}, ${plan.selectedColor}) to ${plan.deliveryLocation} is confirmed! Total na ${totalStr}. We dey pack am now!`;
      }
      return `🎉 Perfect! Your order for ${pName} (Size: ${plan.selectedSize}, Color: ${plan.selectedColor}) to ${plan.deliveryLocation} has been confirmed! Total: ${totalStr}.`;

    case 'PROMPT_CONFIRMATION':
      if (tone === 'warm_nigerian') {
        return `Great choice! ${pName} in Size ${plan.selectedSize} (${plan.selectedColor}). Delivery to ${plan.deliveryLocation} na ${feeStr}. Total comes to ${totalStr}. Make I lock the order for you?`;
      }
      return `Great choice! ${pName} in Size ${plan.selectedSize} (${plan.selectedColor}). Delivery to ${plan.deliveryLocation} is ${feeStr}. Total is ${totalStr}. Should I place the order for you?`;

    case 'PROMPT_MISSING_SIZE':
      const availableSizes = plan.targetProduct?.sizes.join(', ') || 'standard';
      if (tone === 'warm_nigerian') {
        return `Which size you go take for the ${pName}? Available sizes na: ${availableSizes}.`;
      }
      return `Got it! What size would you like for the ${pName}? Available sizes: ${availableSizes}.`;

    case 'PROMPT_MISSING_COLOR':
      const availableColors = plan.targetProduct?.colors.join(', ') || 'standard';
      if (tone === 'warm_nigerian') {
        return `Which color you prefer for the ${pName}? Available colors na: ${availableColors}.`;
      }
      return `What color would you prefer for the ${pName}? Available colors: ${availableColors}.`;

    case 'PROMPT_MISSING_LOCATION':
      if (tone === 'warm_nigerian') {
        return `Where make we send your ${pName}? (e.g. Lekki, Ikeja, Abuja)`;
      }
      return `Got it! Where would you like us to deliver your ${pName}? (e.g. Lekki, Ikeja, Abuja)`;

    case 'SHOW_CATALOG':
      const catList = catalog.map((p) => `• ${p.name} — ${formatNaira(p.price_ngn)}`).join('\n');
      if (tone === 'warm_nigerian') {
        return `See wetin we get for store boss:\n\n${catList}\n\nWhich one you wan buy?`;
      }
      return `Here are our available items:\n\n${catList}\n\nWhich item would you like to order?`;

    case 'ANSWER_PRICE_AND_DETAILS':
      return `The ${pName} is ${priceStr}. Would you like to reserve one today?`;

    case 'GENERAL_HELP':
    default:
      return "How can I help you choose your outfit today? Feel free to ask about prices, sizes, or delivery options!";
  }
}
